          println("home would mean nothing. The scripted arm travels LESS and covers MORE.")

          showSignals(
              "scripted" to breadth[0],
              "one global rule" to breadth[1],
              channel = "breadth",
              title = "sites occupied, per step",
              yTitle = "of 6",
          )

          // Try this: set `order` to `(0 until 6).toList()` for every agent — same script, no rotation —
          // and the scripted arm collapses towards the global one. The rotation IS the division of labour.
  - create:
      box: regime
      name: "Phases: flock, scatter, flock, scatter"
      frame: { x: 60.0, y: 2040.0, w: 340.0, h: 100.0 }
      properties:
        code: |
          /*
          Phases: the same population, told to do different things at different times.

          Ninety agents, four 5 s phases — flock, scatter, flock, scatter. `phase("name")` is just a label
          on a stretch of a program, but because every agent is running its own program, a phase change is
          ninety independent decisions rather than a global mode switch.

          Measured with alife.kt's own polarization, through asBoidFlock(): 1 is everybody heading the same
          way, 0 is no agreement. Nothing here asserts the phases worked — the plot shows whether they did.
          */

          /*
          Two things about the initial condition, and both of them are the whole reason this figure works.

          RANDOM headings, not tangential ones. Ninety agents on a ring all facing along it is perfectly
          symmetric, so their velocities cancel and polarization is EXACTLY 0.0 — and because align and
          cohere preserve that symmetry, it is a fixed point: the first flock phase then reads 0.000 for
          five seconds and the figure looks broken. A symmetric start is not disordered, it is cancelling.

          And a velocity at all, rather than rest: align steers toward the mean NEIGHBOUR velocity, and a
          population at rest has none — rest is not disordered, it is empty.
          */
          val rng = kotlin.random.Random(5L)
          val w = ScriptWorld(width = 220.0, height = 220.0, seed = 5L)
          repeat(90) { i ->
              val a = 2.0 * Math.PI * i / 90
              val h = rng.nextDouble(0.0, 2.0 * Math.PI)
              w.spawn(
                  110.0 + Math.cos(a) * 40.0,
                  110.0 + Math.sin(a) * 40.0,
                  maxSpeed = 30.0,
                  vx = Math.cos(h) * 12.0,
                  vy = Math.sin(h) * 12.0,
              ) {
                  forever {
                      phase("flock") {
                          moveFor(5.0) {
                              align(range = 26.0)
                              cohere(range = 26.0, weight = 0.5)
                              separate(range = 7.0)
                              avoidEdges()
                          }
                      }
                      // turn = 40, not 6: at 60 Hz a small turn random-walks a heading less than a radian
                      // across 5 s, which PRESERVES the alignment it inherited instead of breaking it.
                      phase("scatter") {
                          moveFor(5.0) {
                              wander(turn = 40.0)
                              separate(range = 9.0)
                              avoidEdges()
                          }
                      }
                  }
              }
          }

          val order = mutableListOf<Double>()
          repeat(1200) {
              w.step()
              val f = w.asBoidFlock()
              order += polarization(f.vx, f.vy)
          }

          println("phase means over the last second of each 5 s phase:")
          ["flock" to 0, "scatter" to 1, "flock" to 2, "scatter" to 3].forEach { (name, k) ->
              println("  %-8s %.3f".format(name, order.subList(k * 300 + 240, k * 300 + 300).average()))
          }

          /*
          One output, on one channel. Two panels in a box stack on top of each other, and the plot IS the
          claim here — a picture of ninety trails is a grey doughnut whichever phase drew it.
          `marks` only on the two scatter boundaries: a mark per phase repeats "flock"/"scatter" four
          times in the legend, and a mark at step 0 labels nothing.
          */
          showSignals(
              "polarization" to order,
              channel = "order",
              title = "alignment: flock, scatter, flock, scatter — 5 s each",
              marks = ["scatter" to 300.0, "scatter" to 900.0],
          )

          /*
           Try this: drop `turn = 40.0` to 6.0 and watch the scatter phases stop working — polarization
           stays high, because a gentle random walk does not decorrelate a heading inside five seconds.
           That was a real bug in this demo's first version, and the plot is what caught it.
           */
  - execute: { box: one_agent, property: code }
  - await: {}
  - execute: { box: patrol, property: code }
  - await: {}
  - execute: { box: regime, property: code }
  - await: {}

before:
name: browse_embeds
description: >
  The three inspector embeds, one box each. Box 1 puts a map of mixed values into tree(...): a data
  class, a DoubleArray, a 5000-element list (paged 200 at a time), a map with object keys and a
  two-node loop (marked with a ring arrow, not opened forever). Box 2 shows column(...). Box 3 keeps
  running and adds a reading every half second; open "readings" and watch it grow without a re-run.
  Box 4 is logs(...) filtered to one channel, with a block whose id contains parentheses.
  Run each box; box 3 needs Launch (it loops). See dev_docs/INSPECTOR_EMBEDS.md.
operations:
  - create:
      box: tree_box
      name: "1 - tree(): any value, lazily"
      frame: { x: 60.0, y: 60.0, w: 440.0, h: 60.0 }
      properties:
        code: |
          // Any value can go into tree(...): maps, lists, arrays, data classes, your own classes.
          // Each row shows name, type and a one-line summary; click a triangle (or use the arrow keys) to open.
          // Type **/tag into the filter: it runs scene.graphPaths("**/tag") and lists the matching paths.
          // Press p on a row to copy its path, e.g. particle/age, then scene.graphPath("particle/age") reads it.
          data class Particle(val position: Vec3, val age: Double, val tag: String)
          class Node(val name: String) {
              var next: Node? = null
          }

          val a = Node("a")
          val b = Node("b")
          a.next = b
          b.next = a // a loop: shown with ↺, not opened forever

          val scene = linkedMapOf(
              "particle" to Particle(Vec3(1f, 2f, 0.5f), 0.25, "spark"),
              "weights" to doubleArrayOf(0.1, 0.4, 0.5),
              "many" to List(5000) { it * it }, // arrives 200 rows at a time
              "byKey" to
                  mapOf(
                      Particle(Vec3(0f, 0f, 0f), 0.0, "origin") to "an object as a key",
                      1 to "one",
                      "1" to "the string one",
                  ),
              "ring" to a,
              "missing" to null,
          )
          tree("tree", scene)
  - create:
      box: column_box
      name: "2 - column(): Finder columns"
      frame: { x: 620.0, y: 60.0, w: 440.0, h: 60.0 }
      properties:
        code: |
          // The same kind of value as Finder-style columns: choosing a row opens it in the next column.
          data class Layer(val name: String, val visible: Boolean, val points: IntArray)

          val document = linkedMapOf(
              "layers" to listOf(Layer("dots", true, intArrayOf(2, 4, 8, 16)), Layer("lines", false, intArrayOf())),
              "camera" to mapOf("x" to 10, "y" to 20, "zoom" to 1.5),
              "title" to "a document\nwith two lines",
          )
          column("columns", document)
  - create:
      box: live_box
      name: "3 - a tree that follows the value"
      frame: { x: 60.0, y: 760.0, w: 440.0, h: 60.0 }
      properties:
        code: |
          // Open rows follow the value. This box keeps running and adds a reading every half second;
          // open "readings" in the tree and watch its size and last rows change without re-running.
          val readings = mutableListOf<Double>()
          val state = linkedMapOf<String, Any?>("readings" to readings, "last" to null)
          tree("live", state)

          frames {
              var next = System.currentTimeMillis()
              while (frame()) {
                  if (System.currentTimeMillis() >= next && readings.size < 120) {
                      next += 500
                      readings += Math.round(Math.sin(readings.size * 0.3) * 1000) / 1000.0
                      state["last"] = readings.last()
                  }
              }
          }
  - create:
      box: logs_box
      name: "4 - logs(): one channel, with find"
      frame: { x: 620.0, y: 760.0, w: 440.0, h: 60.0 }
      properties:
        code: |
          // logs(...) streams Field's log into a panel; this one only shows the "demo" channel.
          // Type in its find box (or press /) to narrow it; scroll up and new rows wait behind "↓ N new".
          logs("logs") { channel("demo") }

          val log = afield.ai.diagnostics.LogDispatcher
          log.log(
              afield.ai.diagnostics.LogEvent(
                  "demo",
                  "starting a job",
                  blockId = "job (1)",
                  boundary = afield.ai.diagnostics.BlockBoundary.BEGIN,
              ),
          )
          for (i in 1..3) log.log(afield.ai.diagnostics.LogEvent("demo", "step $i of 3", blockId = "job (1)"))
          log.log(
              afield.ai.diagnostics.LogEvent(
                  "demo",
                  "done",
                  blockId = "job (1)",
                  boundary = afield.ai.diagnostics.BlockBoundary.END,
              ),
          )
          log.log(afield.ai.diagnostics.LogEvent("demo warning", "a warning row is coloured"))
  - execute: { box: tree_box, property: code }
  - execute: { box: column_box, property: code }
  - launch: { box: live_box, property: code }
  - execute: { box: logs_box, property: code }
  - await: { wait: pending }
  - wait: { frames: 90 }
  - stop: { box: live_box }

