  and checks exactly that: the twelve summary channels come back **bit-identical** between the two
  pipelines, and both agree with the closed form of the field to within half a code.

  What you are looking at is the **cut**, not a level: the descent stops at depth 1 over empty
  space and is chased to the leaves inside a tight cluster, so the cells you see are different sizes
  and they tile the frame exactly. Without a criterion a consumer takes one level, and one level of
  a tree is a grid — which is the complaint the flat overlay deserves and this answers.

  Things worth trying in the quadtree box:

    - `threshold` on the cut, from `0.2f` up to `0.29f` and down to `0.05f`. A uniformly filled cell
      has a spatial standard deviation of `1/sqrt(12) = 0.289` of its own width, so the criterion is
      asking "is the mass smaller than the cell", and 0.289 is the value at which it stops being
      able to tell.
    - `criterion = FabricatePassLibrary.SubdivisionCriterion.OCCUPANCY`, which refines along the
      *boundary* of the occupied region instead of inside it.
    - `depth`, from `4` down to `2`. This is the tree, not the cut: at depth 2 a leaf holds a
      sixteenth of the set, and at depth 5 most leaves hold one point, whose covariance is singular
      — so every cell draws a dot and no ring, the honest picture of what one point knows about
      shape.
    - `densityScale`. A node's weight is its density against a uniform spread, which is unbounded in
      a way a raster's mean coverage is not: a point set can put half its mass in one cell. This is
      the knob for bringing a crowded leaf level back into the range an 8-bit readback can show, and
      it scales the weight and the moments together so every ratio taken from them is unchanged.
    - `pointGrid = 32`. Four times the points, sixteen times the sorting work, and the same chain
      shape — the pass count does not move, because the sort's cost is inside two passes rather than
      spread across them.
    - `println(tree.plan.report())`. The line to look at is `quadtree-sorted`, which every leaf pass
      reads and which therefore stays alive across the whole tree while the reduction levels hand
      their targets to each other.

  Nothing here is persistent. The points move, and the codes, the sort, the node ranges and every
  level of the tree are rebuilt from nothing on the next frame — which is what makes a GPU quadtree
  worth having over one you update.

  `dev_docs/FOUR_PASS_CHAIN.md` is the write-up, and
  `tools/run_field_tests.py --id four.quadtree-chain.smoke` is this chain driven headlessly: the
  sort checked as a permutation, the keys checked as ordered, the root node's range checked to be
  the whole array, and the summaries checked against the raster producer's to the last code.
operations:
  # 1. the renderer: owns the Window and pumps the loop. Run this one first.
  - create:
      box: mq_renderer
      name: renderer
      frame: { x: 40.0, y: 40.0, w: 300.0, h: 100.0 }
      properties:
        code: |
          import afield.graphics.vulkan.util.Options

          prop<Window>(window)
          prop<Renderer>(renderer)
          Options.enableHDR = false
          Options.profiling = false
          once.renderer {
              window = Window("Morton quadtree")
              Renderer(window)
          }
          println("renderer ready")
          start(renderer::run)
  # 2. the bundle: no scene, same as its companion. The chain synthesises its own points.
  - create:
      box: mq_bundle
      name: bundle
      frame: { x: 380.0, y: 40.0, w: 300.0, h: 100.0 }
      properties:
        code: |
          // `afield.graphics.scene.fabricated` is not among a box's automatic imports, unlike `afield.graphics.scene`.
          import afield.graphics.scene.fabricated.StandardRenderer
          import afield.graphics.scene.fabricated.applyScenePlan

          prop<StandardRenderer.Bundle>(bundle)

          once.bundle {
              val b = StandardRenderer.build(
                  renderer,
                  StandardRenderer.Config(
                      renderWidth = 1024,
                      renderHeight = 1024,
                      backgroundColor = Vector3f(0.02f, 0.02f, 0.03f),
                  ),
              )
              b.applyScenePlan()
              b.present(renderer = renderer)
              b.attachTo(renderer)
              b
          }
          println("bundle ready: ${bundle.postStack.names()}")
  # 3. the quadtree: points, a sort, node ranges, a summary, and an overlay that draws it.
  - create:
      box: mq_tree
      name: morton quadtree
      frame: { x: 720.0, y: 40.0, w: 320.0, h: 100.0 }
      properties:
        code: |
          import afield.graphics.scene.fabricated.FabricatePassChain
          import afield.graphics.scene.fabricated.FabricatePassLibrary
          import afield.graphics.scene.fabricated.FabricatePassSize
          import afield.graphics.scene.fabricated.FabricatePassSpec
          import afield.graphics.scene.fabricated.addPassChain
          import org.lwjgl.vulkan.VK10.VK_FORMAT_R32G32B32A32_SFLOAT

          prop<afield.graphics.scene.fabricated.FabricateBuiltChain>(tree)

          val grid = 16 // 16x16 = 256 points, one per texel of the point texture
          val depth = 4 // 16x16 leaf cells, so 8 bits of Morton code

          // The point set: three orbiting clusters, two of them stretched and leaning. One point
          // per texel, as (x, y, weight, value) — the layout `mortonPointQuadtree` reads.
          val pointsFragment =
              """
              #version 450
              layout(location = 0) in vec2 vUv;
              layout(push_constant) uniform PointPush {
                  float time;
              } push;
              layout(location = 0) out vec4 outPoint;

              const int WIDTH = $grid;

              float hash1(float n) { return fract(sin(n) * 43758.5453123); }

              void main() {
                  ivec2 p = ivec2(gl_FragCoord.xy);
                  float i = float(p.y * WIDTH + p.x);
                  int which = int(mod(i, 3.0));
                  float t = push.time;

                  vec2 centre = which == 0 ? vec2(0.34 + 0.06 * sin(t), 0.36)
                              : which == 1 ? vec2(0.68, 0.34 + 0.06 * cos(t * 0.8))
                                           : vec2(0.52 + 0.04 * sin(t * 0.5), 0.70);
                  vec2 skew = which == 0 ? vec2(1.0, 1.0) : which == 1 ? vec2(2.0, 0.45) : vec2(0.45, 1.8);
                  float lean = which == 0 ? 0.0 : which == 1 ? 0.5 + 0.3 * sin(t * 0.4) : -0.7 - 0.3 * cos(t * 0.3);
                  float radius = which == 0 ? 0.10 : 0.06;

                  float angle = hash1(i * 1.7 + 3.0) * 6.2831853;
                  vec2 offset = vec2(cos(angle), sin(angle)) * (radius * pow(hash1(i * 2.3 + 11.0), 0.7)) * skew;
                  vec2 turned = vec2(offset.x * cos(lean) - offset.y * sin(lean),
                                     offset.x * sin(lean) + offset.y * cos(lean));

                  outPoint = vec4(clamp(centre + turned, vec2(0.01), vec2(0.99)),
                                  0.35 + 0.65 * hash1(i * 3.1 + 7.0),
                                  0.2 + 0.7 * hash1(i * 5.9 + 19.0));
              }
          """

          /*
          A picture of the points to draw the tree over. Every texel gathers every point, which
          is a scatter turned inside out — the only way a fragment shader draws a point set, and
          the same reason the sort below is a gather.
          */
          val splatFragment =
              """
              #version 450
              layout(location = 0) in vec2 vUv;
              layout(set = 0, binding = 0) uniform sampler2D sourceTex;
              layout(location = 0) out vec4 outColor;

              const int COUNT = ${grid * grid};
              const int WIDTH = $grid;

              void main() {
                  float mass = 0.0;
                  float value = 0.0;
                  for (int i = 0; i < COUNT; ++i) {
                      vec4 point = texelFetch(sourceTex, ivec2(i % WIDTH, i / WIDTH), 0);
                      float d = length(vUv - point.xy) / 0.02;
                      float falloff = exp(-0.5 * d * d) * point.z;
                      mass += falloff;
                      value += falloff * point.w;
                  }
                  // The value is a *ratio* — Σwv/Σw — so it stays at full strength wherever the
                  // mass is merely small rather than zero, and writing it into a channel of its own
                  // paints the whole frame with the faintest halo of the cloud. Multiply it by the
                  // mass: colour where there is something, black where there is not.
                  float m = clamp(mass * 0.06, 0.0, 1.0);
                  float v = mass > 0.0 ? value / mass : 0.0;
                  outColor = vec4(mix(vec3(0.20, 0.35, 0.95), vec3(1.0, 0.85, 0.35), v) * m, 1.0);
              }
          """

          // Declared every run, like its companion: `addPassChain` replaces by name, and nothing in
          // this chain is persistent, so the whole tree simply rebuilds on the next frame.
          tree = bundle.addPassChain(
              [
                  FabricatePassSpec(
                      name = "points",
                      fragment = pointsFragment,
                      size = FabricatePassSize.Absolute(grid, grid),
                      /*
                      fp32 throughout: a Morton code and a point index are exact integers rather
                      than quantities, and a code that rounds is a point that changes cell at
                      the *top* of the tree.
                      */
                      format = VK_FORMAT_R32G32B32A32_SFLOAT,
                      source = FabricatePassChain.CHAIN_INPUT,
                      push = mapOf("time" to 0f),
                  ),
                  FabricatePassSpec(
                      name = "view",
                      fragment = splatFragment,
                      size = FabricatePassSize.Absolute(512, 512),
                      format = VK_FORMAT_R32G32B32A32_SFLOAT,
                      source = "points",
                  ),
              ] +
                  FabricatePassLibrary.mortonPointQuadtree(
                      prefix = "quadtree",
                      points = "points",
                      pointGrid = grid,
                      depth = depth,
                      /*
                      A quarter of the points can land in one leaf cell, whose density against a
                      uniform spread is then about 64. Correct, and four hundred times what an 8-bit
                      preview of that plane could show; this only affects looking at it.
                      */
                      densityScale = 1f / 64f,
                  ) +
                  FabricatePassLibrary.adaptiveSummaryCells(
                      /*
                      The descent: from depth 1 down, stopping where a node already describes its
                      points well enough. SPREAD refines where the mass is *narrower than the cell
                      holding it* — which needs the second moments, and is therefore a criterion an
                      occupancy quadtree cannot express at all. Empty space stops at depth 1; a tight
                      cluster is chased to the leaves.
                      */
                      prefix = "quadtree",
                      name = "cut",
                      over = "view",
                      coarsest = 1,
                      finest = depth,
                      criterion = FabricatePassLibrary.SubdivisionCriterion.SPREAD,
                      threshold = 0.2f,
                      weightGain = 40f,
                  ),
              printReport = true,
          )
          bundle.attachTo(renderer)
          bundle.present(renderer = renderer)

          /*
          ── live knobs. One bound lambda moves the points, and everything downstream — codes,
             ranks, the sorted array, every node's range and every level of the summary — is
             recomputed from them on each frame.
          */
          tree["time"] = { renderer.frameCounter * 0.01f }
          tree["sigma"] = 1.2f
          tree["weightGain"] = 40f
          tree["underGain"] = 0.5f
          // Reaches every level of the descent at once: one number re-cuts the whole tree on the
          // next frame, with nothing rebuilt and nothing reallocated.
          tree["threshold"] = 0.2f

          println(
              "morton quadtree: ${tree.names().size} passes over ${grid * grid} points, " +
                  "leaf level ${tree.targetOf("quadtree-range-$depth")?.width}² nodes",
          )
  - connect: { parent: mq_renderer, child: mq_bundle }
  - connect: { parent: mq_bundle, child: mq_tree }
  - launch: { box: mq_renderer, property: code, strand: renderer }
  - await: {}
  - execute: { box: mq_bundle, property: code }
  - await: {}
  - execute: { box: mq_tree, property: code }
  - await: {}
  - wait: { frames: 24 }

before:
name: gpu_probe_bench_build
description: |
  Builds the loadable `gpuProbe` bench document. Four boxes: a renderer, the whole idiom on one
  screen, the pressure-projection chain the workspace document actually runs, and a deliberate
  under-dispatch so a reader can watch the sentinel fire.

  This transcript is what built `dev_docs/agents/demos/gpu_probe_bench/`;
  re-running it rebuilds that document. It only creates and connects the boxes -- it does not
  launch them, so no window opens while the document is being written.

  Registered `COMPILE_ONLY`: replaying the boxes would need a window, since box 1 opens one and
  Field 4 has no headless mode. What the registration buys is that all four box bodies are
  compiled against Field's real K2 and preamble import set on every build -- the one place box code
  can diverge from `jvmMain` and that no Gradle gate could otherwise see. The GPU numbers are
  asserted separately by the `four.gpu-probe.pressure-chain` and `four.gpu-probe.self-check`
  FIELD_TESTs.
operations:
  - create:
      box: probe_renderer
      name: 1 - a window, because there is no headless mode
      frame: { x: 40.0, y: 40.0, w: 360.0, h: 110.0 }
      properties:
        code: |
          import afield.graphics.vulkan.util.Options

          /*
          Field 4 has no headless mode: a compute-only dispatch still needs a Window for
          the device to exist, and it needs an awake display. So every box below is a child of
          this one and resolves `renderer` from it.

          RUN THIS BOX FIRST. Before it has run there is no Renderer anywhere and the others
          fail with a context error rather than a GPU one.
          */
          prop<Window>(window)
          prop<Renderer>(renderer)
          Options.enableHDR = false
          once.renderer {
              window = Window("Field · gpuProbe bench")
              Renderer(window)
          }
          start(renderer::run)
  - create:
      box: probe_hello
      name: 2 - the whole idiom, on one screen
      frame: { x: 40.0, y: 200.0, w: 420.0, h: 150.0 }
      properties:
        code: |
          /*
          A fixture, a shader, a dispatch, a wait, a readback, three claims. What matters is
          what is NOT here: no `defaultBuffer` whose access pattern you have to remember
          (`fixture` insists on streamReads(), because a host read out of write-combined
          memory is pathological); no `computeMemoryBarrier` task to append by hand; no frame
          count guessed by feel; and no `finally { renderer.computeList.modules.remove(key) }`.
          */
          val probe = GpuProbe(renderer, "hello")
          val out = probe.fixture("out", 256)

          probe
              .stage(
                  "fives",
                  """#version 450
          #extension GL_EXT_buffer_reference : require
          layout(std430, buffer_reference) buffer Field { vec4 v[]; };
          layout(local_size_x = 64) in;
          layout(push_constant) uniform Push { Field target; uint count; } pc;
          void main() {
              uint id = gl_GlobalInvocationID.x;
              if (id >= pc.count) return;
              pc.target.v[id] = vec4(5.0, float(id), 0.0, 0.0);
          }
          """,
              )
              .dispatch(groups = 1) {
                  // Misspell `target` here and this line throws, listing the slots the shader does
                  // have. `Structure.bind` on its own would have accepted the typo and bound nothing.
                  bind("target") { out }
                  bind("count") { 64 }
              }

          frames {
              try {
                  /*
                  `arm` prefills the output with a sentinel and `stillWaiting` is a CONDITION,
                  so this loop ends when the GPU has demonstrably written every slot. A shader
                  compiles asynchronously and a module whose shader is not ready dispatches as
                  a SILENT no-op, which is why `repeat(4) { frame() }` is a hope and not a wait.
                  */
                  probe.arm(out)
                  while (probe.stillWaiting()) frame()

                  val got = probe.read(out)
                  println("landed after ${probe.framesToLand} pumped frame(s)")
                  probe.exactly("cell 0 value", got[0], 5f, buffer = "out", index = 0)
                  probe.exactly("cell 63 id tag", got[63 * 4 + 1], 63f, buffer = "out", index = 253)
                  probe.allFinite("out", got, buffer = "out")
                  /*
                  `{ println(it) }` rather than the default, and this is not cosmetic:
                  box `println` is rewritten by the K2 REPL into `_printlnHere`, which posts
                  to THIS box's output. A `println` inside the library is an ordinary one and
                  goes to the server's stdout, where nobody looking at this box can see it.
                  */
                  probe.verdict("hello") { println(it) }
              } finally {
                  probe.close()
              }
          }
  - create:
      box: probe_chain
      name: 3 - divergence, 12 Jacobi sweeps, project
      frame: { x: 520.0, y: 200.0, w: 460.0, h: 160.0 }
      properties:
        code: |
          /*
          The chain the workspace document actually runs, at a size that fits in a box.

          A MAC (staggered) grid: u on the left x-face of each cell, v on the bottom y-face,
          both in the x and y of one vec4. Divergence is a forward difference and the pressure
          gradient is a backward difference, so the two are exact adjoints and div.grad is
          precisely the 5-point Laplacian the Jacobi sweeps invert.
          */
          val N = 32
          val CELLS = N * N
          val FLOATS = CELLS * 4
          val GROUPS = CELLS / 64
          val SWEEPS = 12

          val head =
              """#version 450
          #extension GL_EXT_buffer_reference : require
          layout(std430, buffer_reference) buffer Field { vec4 v[]; };
          layout(local_size_x = 64) in;
          """

          val divergenceGlsl =
              head +
                  """
          layout(push_constant) uniform Push { Field velocity; Field divergence; uint side; } pc;
          void main() {
              uint id = gl_GlobalInvocationID.x;
              uint n = pc.side;
              if (id >= n * n) return;
              uint i = id % n; uint j = id / n;
              float uL = (i == 0u)     ? 0.0 : pc.velocity.v[id].x;
              float uR = (i + 1u >= n) ? 0.0 : pc.velocity.v[id + 1u].x;
              float vB = (j == 0u)     ? 0.0 : pc.velocity.v[id].y;
              float vT = (j + 1u >= n) ? 0.0 : pc.velocity.v[id + n].y;
              pc.divergence.v[id] = vec4((uR - uL) + (vT - vB), 0.0, 0.0, 0.0);
          }
          """

          val jacobiGlsl =
              head +
                  """
          layout(push_constant) uniform Push { Field pressureIn; Field pressureOut; Field divergence; uint side; } pc;
          void main() {
              uint id = gl_GlobalInvocationID.x;
              uint n = pc.side;
              if (id >= n * n) return;
              uint i = id % n; uint j = id / n;
              float pL = pc.pressureIn.v[(i == 0u)     ? id : id - 1u].x;
              float pR = pc.pressureIn.v[(i + 1u >= n) ? id : id + 1u].x;
              float pB = pc.pressureIn.v[(j == 0u)     ? id : id - n ].x;
              float pT = pc.pressureIn.v[(j + 1u >= n) ? id : id + n ].x;
              pc.pressureOut.v[id] = vec4((pL + pR + pB + pT - pc.divergence.v[id].x) * 0.25, 0.0, 0.0, 0.0);
          }
          """

          val projectGlsl =
              head +
                  """
          layout(push_constant) uniform Push { Field velocity; Field pressure; Field velocityOut; uint side; } pc;
          void main() {
              uint id = gl_GlobalInvocationID.x;
              uint n = pc.side;
              if (id >= n * n) return;
              uint i = id % n; uint j = id / n;
              float pC = pc.pressure.v[id].x;
              float pL = pc.pressure.v[(i == 0u) ? id : id - 1u].x;
              float pB = pc.pressure.v[(j == 0u) ? id : id - n ].x;
              float u = (i == 0u) ? 0.0 : pc.velocity.v[id].x - (pC - pL);
              float v = (j == 0u) ? 0.0 : pc.velocity.v[id].y - (pC - pB);
              pc.velocityOut.v[id] = vec4(u, v, 0.0, 0.0);
          }
          """

          val probe = GpuProbe(renderer, "chain")
          val velocity = probe.fixture("velocity", FLOATS)
          val velocityOut = probe.fixture("velocityOut", FLOATS)
          val divergence = probe.fixture("divergence", FLOATS)
          val pressureA = probe.fixture("pressureA", FLOATS)
          val pressureB = probe.fixture("pressureB", FLOATS)

          /*
          A multi-scale divergent field. Jacobi kills high-frequency error in a handful of
          sweeps and low frequency in hundreds, so a single-scale field would report either a
          spectacular reduction or a negligible one and neither would say anything.
          */
          val seeded = FloatArray(FLOATS)
          for (j in 0 until N) for (i in 0 until N) {
              val x = (i + 0.5) / N
              val y = (j + 0.5) / N
              val o = (j * N + i) * 4
              seeded[o] =
                  (kotlin.math.sin(2 * Math.PI * x * 3) * kotlin.math.cos(2 * Math.PI * y * 2) +
                          0.5 * kotlin.math.sin(2 * Math.PI * x * 9))
                      .toFloat()
              seeded[o + 1] =
                  (kotlin.math.cos(2 * Math.PI * x * 2) * kotlin.math.sin(2 * Math.PI * y * 3) +
                          0.5 * kotlin.math.sin(2 * Math.PI * y * 7))
                      .toFloat()
          }
          probe.upload(velocity, seeded)
          probe.fill(pressureA, 0f)
          probe.fill(pressureB, 0f)

          // The oracle: the divergence stencil again, in Kotlin, so the "after" number is not
          // computed by the thing being graded.
          fun divergenceOf(f: FloatArray): FloatArray {
              val d = FloatArray(CELLS)
              for (j in 0 until N) for (i in 0 until N) {
                  val id = j * N + i
                  val uL = if (i == 0) 0f else f[id * 4]
                  val uR = if (i + 1 >= N) 0f else f[(id + 1) * 4]
                  val vB = if (j == 0) 0f else f[id * 4 + 1]
                  val vT = if (j + 1 >= N) 0f else f[(id + N) * 4 + 1]
                  d[id] = (uR - uL) + (vT - vB)
              }
              return d
          }

          fun maxAbs(a: FloatArray): Float {
              var m = 0f
              for (v in a) if (v.isFinite()) m = maxOf(m, kotlin.math.abs(v))
              return m
          }

          /*
          Three stages. Note there is ONE `stage` call for all twelve Jacobi sweeps: a Stage is
          one shader and one compile, and each `dispatch` adds a workgroup launch plus its own
          barrier, so sweep k reads what sweep k-1 wrote. Twelve compiles would have been the
          obvious mistake. SWEEPS is even, so the answer lands back in pressureA.
          */
          probe.stage("divergence", divergenceGlsl).dispatch(groups = GROUPS) {
              bind("velocity") { velocity }
              bind("divergence") { divergence }
              bind("side") { N }
          }
          val jacobi = probe.stage("jacobi", jacobiGlsl)
          for (k in 0 until SWEEPS) {
              val from = if (k % 2 == 0) pressureA else pressureB
              val to = if (k % 2 == 0) pressureB else pressureA
              jacobi.dispatch(groups = GROUPS, label = "sweep" + k) {
                  bind("pressureIn") { from }
                  bind("pressureOut") { to }
                  bind("divergence") { divergence }
                  bind("side") { N }
              }
          }
          probe.stage("project", projectGlsl).dispatch(groups = GROUPS) {
              bind("velocity") { velocity }
              bind("pressure") { pressureA }
              bind("velocityOut") { velocityOut }
              bind("side") { N }
          }

          frames {
              try {
                  probe.arm(velocityOut, divergence)
                  while (probe.stillWaiting()) frame()
                  println(
                      "chain: " +
                          probe.stageList.size +
                          " stages, " +
                          probe.stageList.sumOf { it.dispatchCount } +
                          " dispatches, landed after " +
                          probe.framesToLand +
                          " frame(s)",
                  )

                  // Claim 1: the divergence pass against the closed form, at every cell.
                  val gpuDiv = probe.read(divergence)
                  val cpuDiv = divergenceOf(seeded)
                  var worstErr = 0f
                  var worstAt = -1
                  for (id in 0 until CELLS) {
                      val e = kotlin.math.abs(gpuDiv[id * 4] - cpuDiv[id])
                      if (e > worstErr) {
                          worstErr = e
                          worstAt = id
                      }
                  }
                  val before = maxAbs(cpuDiv)
                  probe.atMost(
                      "divergence pass vs closed form",
                      worstErr,
                      1e-6f,
                      buffer = "divergence",
                      index = worstAt,
                  )
                  /*
                  Measured 2.546231 on this fixture, which is deterministic CPU arithmetic.
                  A floor of 2.2 fails if somebody edits the seed into something flat, which
                  is the only way the rest of this box could pass while meaning nothing.
                  */
                  probe.atLeast("input field max |div|", before, 2.2f, buffer = "velocity")

                  // Claim 2: the sweep. Pressure re-zeroed each sample, so frames x SWEEPS is
                  // the whole iteration count and the points are comparable.
                  println("  frames  sweeps   max |div| after   reduction")
                  var first = 0f
                  var last = 0f
                  for (f in listOf(1, 2, 4, 8)) {
                      probe.idle()
                      probe.fill(pressureA, 0f)
                      probe.fill(pressureB, 0f)
                      probe.arm(velocityOut)
                      while (probe.stillWaiting()) frame()
                      var pumped = probe.framesToLand
                      while (pumped < f) {
                          frame()
                          pumped++
                      }
                      probe.idle()
                      val after = maxAbs(divergenceOf(probe.read(velocityOut)))
                      if (first == 0f) first = after
                      last = after
                      println("  %6d  %6d   %15.5f   %7.1fx".format(pumped, pumped * SWEEPS, after, before / after))
                  }
                  /*
                  Measured 2584.5x at 96 sweeps and 262.4x between the ends of the sweep.
                  These floors sit just under the measurements on purpose: `>= 30` against
                  2584 is not a test, and a floor that cannot fail is this project's
                  recurring weakness. A chain that lost a barrier reports single digits.
                  */
                  probe.atLeast("reduction, best sample", before / last, 1500f, buffer = "velocityOut")
                  probe.atLeast("extra sweeps helped", first / last, 150f)
                  probe.allFinite("projected field", probe.read(velocityOut), buffer = "velocityOut")
                  probe.verdict("chain") { println(it) }
              } finally {
                  probe.close()
              }
          }
  - create:
      box: probe_caught
      name: 4 - half a grid, so the sentinel fires
      frame: { x: 40.0, y: 420.0, w: 420.0, h: 150.0 }
      properties:
        code: |
          /*
          The same shader as box 2, told to write half as many cells on purpose. This is the
          box that says whether the sentinel is load-bearing: a hand-rolled probe that waits
          `repeat(4) { frame() }` and then reads would report whatever was in the buffer, and
          the half that never ran looks exactly like agreement.
          */
          val probe = GpuProbe(renderer, "caught")
          val out = probe.fixture("out", 256)

          probe
              .stage(
                  "fives",
                  """#version 450
          #extension GL_EXT_buffer_reference : require
          layout(std430, buffer_reference) buffer Field { vec4 v[]; };
          layout(local_size_x = 64) in;
          layout(push_constant) uniform Push { Field target; uint count; } pc;
          void main() {
              uint id = gl_GlobalInvocationID.x;
              if (id >= pc.count) return;
              pc.target.v[id] = vec4(5.0, float(id), 0.0, 0.0);
          }
          """,
              )
              .dispatch(groups = 1) {
                  bind("target") { out }
                  bind("count") { 32 }
              }

          frames {
              try {
                  // Four seconds, not the twelve-second default: this case is MEANT to time out
                  // and the point is the message, not the wait.
                  probe.arm(out, seconds = 4.0)
                  try {
                      while (probe.stillWaiting()) frame()
                      println("NOT CAUGHT - the probe said it landed, which would be a bug in GpuProbe")
                  } catch (e: GpuProbeNeverLanded) {
                      println("caught, as it should be:")
                      for (line in (e.message ?: "").lines()) println("  " + line)
                  }
              } finally {
                  probe.close()
              }
          }
  - connect: { parent: probe_renderer, child: probe_hello }
  - connect: { parent: probe_renderer, child: probe_chain }
  - connect: { parent: probe_renderer, child: probe_caught }
  # Persist the assembled boxes as the loadable document. `save` takes the document
  # DIRECTORY, not a metadata.edn inside it.
  - save: { path: dev_docs/agents/demos/gpu_probe_bench }

after:
name: gpu_probe_bench_build
description: |
  Builds the loadable `gpuProbe` bench document. Four boxes: a renderer, the whole idiom on one
  screen, the pressure-projection chain the workspace document actually runs, and a deliberate
  under-dispatch so a reader can watch the sentinel fire.

  This transcript is what built `dev_docs/agents/demos/gpu_probe_bench/`;
  re-running it rebuilds that document. It only creates and connects the boxes -- it does not
  launch them, so no window opens while the document is being written.

  Registered `COMPILE_ONLY`: replaying the boxes would need a window, since box 1 opens one and
  Field 4 has no headless mode. What the registration buys is that all four box bodies are
  compiled against Field's real K2 and preamble import set on every build -- the one place box code
  can diverge from `jvmMain` and that no Gradle gate could otherwise see. The GPU numbers are
  asserted separately by the `four.gpu-probe.pressure-chain` and `four.gpu-probe.self-check`
  FIELD_TESTs.
operations:
  - create:
      box: probe_renderer
      name: 1 - a window, because there is no headless mode
      frame: { x: 40.0, y: 40.0, w: 360.0, h: 110.0 }
      properties:
        code: |
          import afield.graphics.vulkan.util.Options

          /*
          Field 4 has no headless mode: a compute-only dispatch still needs a Window for
          the device to exist, and it needs an awake display. So every box below is a child of
          this one and resolves `renderer` from it.

          RUN THIS BOX FIRST. Before it has run there is no Renderer anywhere and the others
          fail with a context error rather than a GPU one.
          */
          prop<Window>(window)
          prop<Renderer>(renderer)
          Options.enableHDR = false
          once.renderer {
              window = Window("Field · gpuProbe bench")
              Renderer(window)
          }
          start(renderer::run)
  - create:
      box: probe_hello
      name: 2 - the whole idiom, on one screen
      frame: { x: 40.0, y: 200.0, w: 420.0, h: 150.0 }
      properties:
        code: |
          /*
          A fixture, a shader, a dispatch, a wait, a readback, three claims. What matters is
          what is NOT here: no `defaultBuffer` whose access pattern you have to remember
          (`fixture` insists on streamReads(), because a host read out of write-combined
          memory is pathological); no `computeMemoryBarrier` task to append by hand; no frame
          count guessed by feel; and no `finally { renderer.computeList.modules.remove(key) }`.
          */
          val probe = GpuProbe(renderer, "hello")
          val out = probe.fixture("out", 256)

          probe
              .stage(
                  "fives",
                  """#version 450
          #extension GL_EXT_buffer_reference : require
          layout(std430, buffer_reference) buffer Field { vec4 v[]; };
          layout(local_size_x = 64) in;
          layout(push_constant) uniform Push { Field target; uint count; } pc;
          void main() {
              uint id = gl_GlobalInvocationID.x;
              if (id >= pc.count) return;
              pc.target.v[id] = vec4(5.0, float(id), 0.0, 0.0);
          }
          """,
              )
              .dispatch(groups = 1) {
                  // Misspell `target` here and this line throws, listing the slots the shader does
                  // have. `Structure.bind` on its own would have accepted the typo and bound nothing.
                  bind("target") { out }
                  bind("count") { 64 }
              }

          frames {
              try {
                  /*
                  `arm` prefills the output with a sentinel and `stillWaiting` is a CONDITION,
                  so this loop ends when the GPU has demonstrably written every slot. A shader
                  compiles asynchronously and a module whose shader is not ready dispatches as
                  a SILENT no-op, which is why `repeat(4) { frame() }` is a hope and not a wait.
                  */
                  probe.arm(out)
                  while (probe.stillWaiting()) frame()

                  val got = probe.read(out)
                  println("landed after ${probe.framesToLand} pumped frame(s)")
                  probe.exactly("cell 0 value", got[0], 5f, buffer = "out", index = 0)
                  probe.exactly("cell 63 id tag", got[63 * 4 + 1], 63f, buffer = "out", index = 253)
                  probe.allFinite("out", got, buffer = "out")
                  /*
                  `{ println(it) }` rather than the default, and this is not cosmetic:
                  box `println` is rewritten by the K2 REPL into `_printlnHere`, which posts
                  to THIS box's output. A `println` inside the library is an ordinary one and
                  goes to the server's stdout, where nobody looking at this box can see it.
                  */
                  probe.verdict("hello") { println(it) }
              } finally {
                  probe.close()
              }
          }
  - create:
      box: probe_chain
      name: 3 - divergence, 12 Jacobi sweeps, project
      frame: { x: 520.0, y: 200.0, w: 460.0, h: 160.0 }
      properties:
        code: |
          /*
          The chain the workspace document actually runs, at a size that fits in a box.

          A MAC (staggered) grid: u on the left x-face of each cell, v on the bottom y-face,
          both in the x and y of one vec4. Divergence is a forward difference and the pressure
          gradient is a backward difference, so the two are exact adjoints and div.grad is
          precisely the 5-point Laplacian the Jacobi sweeps invert.
          */
          val N = 32
          val CELLS = N * N
          val FLOATS = CELLS * 4
          val GROUPS = CELLS / 64
          val SWEEPS = 12

          val head =
              """#version 450
          #extension GL_EXT_buffer_reference : require
          layout(std430, buffer_reference) buffer Field { vec4 v[]; };
          layout(local_size_x = 64) in;
          """

          val divergenceGlsl =
              head +
                  """
          layout(push_constant) uniform Push { Field velocity; Field divergence; uint side; } pc;
          void main() {
              uint id = gl_GlobalInvocationID.x;
              uint n = pc.side;
              if (id >= n * n) return;
              uint i = id % n; uint j = id / n;
              float uL = (i == 0u)     ? 0.0 : pc.velocity.v[id].x;
              float uR = (i + 1u >= n) ? 0.0 : pc.velocity.v[id + 1u].x;
              float vB = (j == 0u)     ? 0.0 : pc.velocity.v[id].y;
              float vT = (j + 1u >= n) ? 0.0 : pc.velocity.v[id + n].y;
              pc.divergence.v[id] = vec4((uR - uL) + (vT - vB), 0.0, 0.0, 0.0);
          }
          """

          val jacobiGlsl =
              head +
                  """
          layout(push_constant) uniform Push { Field pressureIn; Field pressureOut; Field divergence; uint side; } pc;
          void main() {
              uint id = gl_GlobalInvocationID.x;
              uint n = pc.side;
              if (id >= n * n) return;
              uint i = id % n; uint j = id / n;
              float pL = pc.pressureIn.v[(i == 0u)     ? id : id - 1u].x;
              float pR = pc.pressureIn.v[(i + 1u >= n) ? id : id + 1u].x;
              float pB = pc.pressureIn.v[(j == 0u)     ? id : id - n ].x;
              float pT = pc.pressureIn.v[(j + 1u >= n) ? id : id + n ].x;
              pc.pressureOut.v[id] = vec4((pL + pR + pB + pT - pc.divergence.v[id].x) * 0.25, 0.0, 0.0, 0.0);
          }
          """

          val projectGlsl =
              head +
                  """
          layout(push_constant) uniform Push { Field velocity; Field pressure; Field velocityOut; uint side; } pc;
          void main() {
              uint id = gl_GlobalInvocationID.x;
              uint n = pc.side;
              if (id >= n * n) return;
              uint i = id % n; uint j = id / n;
              float pC = pc.pressure.v[id].x;
              float pL = pc.pressure.v[(i == 0u) ? id : id - 1u].x;
              float pB = pc.pressure.v[(j == 0u) ? id : id - n ].x;
              float u = (i == 0u) ? 0.0 : pc.velocity.v[id].x - (pC - pL);
              float v = (j == 0u) ? 0.0 : pc.velocity.v[id].y - (pC - pB);
              pc.velocityOut.v[id] = vec4(u, v, 0.0, 0.0);
          }
          """

          val probe = GpuProbe(renderer, "chain")
          val velocity = probe.fixture("velocity", FLOATS)
          val velocityOut = probe.fixture("velocityOut", FLOATS)
          val divergence = probe.fixture("divergence", FLOATS)
          val pressureA = probe.fixture("pressureA", FLOATS)
          val pressureB = probe.fixture("pressureB", FLOATS)

          /*
          A multi-scale divergent field. Jacobi kills high-frequency error in a handful of
          sweeps and low frequency in hundreds, so a single-scale field would report either a
          spectacular reduction or a negligible one and neither would say anything.
          */
          val seeded = FloatArray(FLOATS)
          for (j in 0 until N) for (i in 0 until N) {
              val x = (i + 0.5) / N
              val y = (j + 0.5) / N
              val o = (j * N + i) * 4
              seeded[o] =
                  (kotlin.math.sin(2 * Math.PI * x * 3) * kotlin.math.cos(2 * Math.PI * y * 2) +
                          0.5 * kotlin.math.sin(2 * Math.PI * x * 9))
                      .toFloat()
              seeded[o + 1] =
                  (kotlin.math.cos(2 * Math.PI * x * 2) * kotlin.math.sin(2 * Math.PI * y * 3) +
                          0.5 * kotlin.math.sin(2 * Math.PI * y * 7))
                      .toFloat()
          }
          probe.upload(velocity, seeded)
          probe.fill(pressureA, 0f)
          probe.fill(pressureB, 0f)

          // The oracle: the divergence stencil again, in Kotlin, so the "after" number is not
          // computed by the thing being graded.
          fun divergenceOf(f: FloatArray): FloatArray {
              val d = FloatArray(CELLS)
              for (j in 0 until N) for (i in 0 until N) {
                  val id = j * N + i
                  val uL = if (i == 0) 0f else f[id * 4]
                  val uR = if (i + 1 >= N) 0f else f[(id + 1) * 4]
                  val vB = if (j == 0) 0f else f[id * 4 + 1]
                  val vT = if (j + 1 >= N) 0f else f[(id + N) * 4 + 1]
                  d[id] = (uR - uL) + (vT - vB)
              }
              return d
          }

          fun maxAbs(a: FloatArray): Float {
              var m = 0f
              for (v in a) if (v.isFinite()) m = maxOf(m, kotlin.math.abs(v))
              return m
          }

          /*
          Three stages. Note there is ONE `stage` call for all twelve Jacobi sweeps: a Stage is
          one shader and one compile, and each `dispatch` adds a workgroup launch plus its own
          barrier, so sweep k reads what sweep k-1 wrote. Twelve compiles would have been the
          obvious mistake. SWEEPS is even, so the answer lands back in pressureA.
          */
          probe.stage("divergence", divergenceGlsl).dispatch(groups = GROUPS) {
              bind("velocity") { velocity }
              bind("divergence") { divergence }
              bind("side") { N }
          }
          val jacobi = probe.stage("jacobi", jacobiGlsl)
          for (k in 0 until SWEEPS) {
              val from = if (k % 2 == 0) pressureA else pressureB
              val to = if (k % 2 == 0) pressureB else pressureA
              jacobi.dispatch(groups = GROUPS, label = "sweep" + k) {
                  bind("pressureIn") { from }
                  bind("pressureOut") { to }
                  bind("divergence") { divergence }
                  bind("side") { N }
              }
          }
          probe.stage("project", projectGlsl).dispatch(groups = GROUPS) {
              bind("velocity") { velocity }
              bind("pressure") { pressureA }
              bind("velocityOut") { velocityOut }
              bind("side") { N }
          }

          frames {
              try {
                  probe.arm(velocityOut, divergence)
                  while (probe.stillWaiting()) frame()
                  println(
                      "chain: " +
                          probe.stageList.size +
                          " stages, " +
                          probe.stageList.sumOf { it.dispatchCount } +
                          " dispatches, landed after " +
                          probe.framesToLand +
                          " frame(s)",
                  )

                  // Claim 1: the divergence pass against the closed form, at every cell.
                  val gpuDiv = probe.read(divergence)
                  val cpuDiv = divergenceOf(seeded)
                  var worstErr = 0f
                  var worstAt = -1
                  for (id in 0 until CELLS) {
                      val e = kotlin.math.abs(gpuDiv[id * 4] - cpuDiv[id])
                      if (e > worstErr) {
                          worstErr = e
                          worstAt = id
                      }
                  }
                  val before = maxAbs(cpuDiv)
                  probe.atMost(
                      "divergence pass vs closed form",
                      worstErr,
                      1e-6f,
                      buffer = "divergence",
                      index = worstAt,
                  )
                  /*
                  Measured 2.546231 on this fixture, which is deterministic CPU arithmetic.
                  A floor of 2.2 fails if somebody edits the seed into something flat, which
                  is the only way the rest of this box could pass while meaning nothing.
                  */
                  probe.atLeast("input field max |div|", before, 2.2f, buffer = "velocity")

                  // Claim 2: the sweep. Pressure re-zeroed each sample, so frames x SWEEPS is
                  // the whole iteration count and the points are comparable.
                  println("  frames  sweeps   max |div| after   reduction")
                  var first = 0f
                  var last = 0f
                  for (f in [1, 2, 4, 8]) {
                      probe.idle()
                      probe.fill(pressureA, 0f)
                      probe.fill(pressureB, 0f)
                      probe.arm(velocityOut)
                      while (probe.stillWaiting()) frame()
                      var pumped = probe.framesToLand
                      while (pumped < f) {
                          frame()
                          pumped++
                      }
                      probe.idle()
                      val after = maxAbs(divergenceOf(probe.read(velocityOut)))
                      if (first == 0f) first = after
                      last = after
                      println("  %6d  %6d   %15.5f   %7.1fx".format(pumped, pumped * SWEEPS, after, before / after))
                  }
                  /*
                  Measured 2584.5x at 96 sweeps and 262.4x between the ends of the sweep.
                  These floors sit just under the measurements on purpose: `>= 30` against
                  2584 is not a test, and a floor that cannot fail is this project's
                  recurring weakness. A chain that lost a barrier reports single digits.
                  */
                  probe.atLeast("reduction, best sample", before / last, 1500f, buffer = "velocityOut")
                  probe.atLeast("extra sweeps helped", first / last, 150f)
                  probe.allFinite("projected field", probe.read(velocityOut), buffer = "velocityOut")
                  probe.verdict("chain") { println(it) }
              } finally {
                  probe.close()
              }
          }
  - create:
      box: probe_caught
      name: 4 - half a grid, so the sentinel fires
      frame: { x: 40.0, y: 420.0, w: 420.0, h: 150.0 }
      properties:
        code: |
          /*
          The same shader as box 2, told to write half as many cells on purpose. This is the
          box that says whether the sentinel is load-bearing: a hand-rolled probe that waits
          `repeat(4) { frame() }` and then reads would report whatever was in the buffer, and
          the half that never ran looks exactly like agreement.
          */
          val probe = GpuProbe(renderer, "caught")
          val out = probe.fixture("out", 256)

          probe
              .stage(
                  "fives",
                  """#version 450
          #extension GL_EXT_buffer_reference : require
          layout(std430, buffer_reference) buffer Field { vec4 v[]; };
          layout(local_size_x = 64) in;
          layout(push_constant) uniform Push { Field target; uint count; } pc;
          void main() {
              uint id = gl_GlobalInvocationID.x;
              if (id >= pc.count) return;
              pc.target.v[id] = vec4(5.0, float(id), 0.0, 0.0);
          }
          """,
              )
              .dispatch(groups = 1) {
                  bind("target") { out }
                  bind("count") { 32 }
              }

          frames {
              try {
                  // Four seconds, not the twelve-second default: this case is MEANT to time out
                  // and the point is the message, not the wait.
                  probe.arm(out, seconds = 4.0)
                  try {
                      while (probe.stillWaiting()) frame()
                      println("NOT CAUGHT - the probe said it landed, which would be a bug in GpuProbe")
                  } catch (e: GpuProbeNeverLanded) {
                      println("caught, as it should be:")
                      for (line in (e.message ?: "").lines()) println("  " + line)
                  }
              } finally {
                  probe.close()
              }
          }
  - connect: { parent: probe_renderer, child: probe_hello }
  - connect: { parent: probe_renderer, child: probe_chain }
  - connect: { parent: probe_renderer, child: probe_caught }
  # Persist the assembled boxes as the loadable document. `save` takes the document
  # DIRECTORY, not a metadata.edn inside it.
  - save: { path: dev_docs/agents/demos/gpu_probe_bench }

before:
name: keyframe_editor
description: >
  The keyframe editor (`keyframes(...)`, `public/docs/keyframe_editor.md`) as three boxes.
  `brightness` is a hand-drawn curve played by a `loop` into a meter. `shape` starts a curve with
  one key of each type. `smoothed` draws a smoothed overlay of the curve and keeps it up to date as
  the curve is edited, with `onChange`. CI launches `brightness`, executes the other two, advances
  90 frames and stops.
operations:
  - create:
      box: kf_brightness
      name: brightness
      frame: { x: 40.0, y: 40.0, w: 300.0, h: 100.0 }
      properties:
        code: |
          // Launch this box to play the curve: the playhead sweeps it every four seconds and the
          // meter shows its value. Edit the curve while it plays; your edits are saved with the box.
          val brightness =
              keyframes(name = "brightness", defaults = listOf(vec(0.0, 0.1), vec(1.0, 0.9), vec(2.5, 0.4), vec(4.0, 0.1)))

          lateinit var level: MeterHandle
          controlGroup("level") { level = meter("brightness") }
          displayOpen("level")

          val start = System.nanoTime()
          loop {
              val t = ((System.nanoTime() - start) / 1e9) % 4.0
              brightness.setTime(t)
              level.set(brightness.evaluateValueAt(t))
          }
  - create:
      box: kf_shape
      name: shape
      frame: { x: 760.0, y: 40.0, w: 300.0, h: 100.0 }
      properties:
        code: |
          // Run this box: one key of each type. Right-click a key to change its type.
          val shape = keyframes(
              name = "shape",
              keys = listOf(
                  Keyframe(0.0, 0.1, "linear"),
                  Keyframe(1.0, 0.8, "hold"),
                  Keyframe(2.0, 0.3, "bezierFlat"),
                  Keyframe(3.0, 0.9, "bezierContinuous"),
                  Keyframe(4.0, 0.5, "bezierFree"),
                  Keyframe(5.0, 0.2, "linear"),
              ),
          )
  - create:
      box: kf_smoothed
      name: smoothed
      frame: { x: 40.0, y: 520.0, w: 300.0, h: 100.0 }
      properties:
        code: |
          // Run this box, then edit the curve: the dashed overlay is a smoothed copy of it, and
          // onChange redraws it after every edit.
          val wobble = keyframes(
              name = "wobble",
              defaults = listOf(
                  vec(0.0, 0.2),
                  vec(0.5, 0.9),
                  vec(1.0, 0.1),
                  vec(1.5, 0.8),
                  vec(2.0, 0.3),
              ),
          )

          val smooth = { keys: List<Keyframe> -> with(Functions) { gaussianSmooth(fromKeyframeEditor(keys), sigma = 0.15) } }
          wobble.setOverlay(smooth(wobble.getKeyframes()))
          wobble.onChange = smooth
  - create:
      box: kf_custom
      name: custom types
      frame: { x: 760.0, y: 520.0, w: 300.0, h: 100.0 }
      properties:
        code: |
          /*
          Run this box: three key types written in Kotlin. Each returns the curve's value across a
          segment; u runs 0 to 1, lerp(f) is "f of the way from this key's value to the next".
          Right-click a key and they are in the menu, after the five built in.
          */
          interpolant("overshoot") { lerp(1 + 2.7 * (u - 1).pow(3) + 1.7 * (u - 1).pow(2)) }
          interpolant("wobble") { lerp(u) + 0.08 * sin(u * 6 * PI) * (1 - u) }
          // Deterministic chaos: the logistic map, seeded by where we are, and pinned to both keys.
          interpolant("chaos") {
              var x = 0.1 + 0.8 * u
              repeat(30) { x = 3.97 * x * (1 - x) }
              lerp(u) + 0.25 * sin(PI * u) * (x - 0.5)
          }

          val custom = keyframes(
              name = "custom",
              keys = listOf(
                  Keyframe(0.0, 0.1, "overshoot"),
                  Keyframe(1.5, 0.8, "wobble"),
                  Keyframe(3.0, 0.3, "chaos"),
                  Keyframe(4.5, 0.6, "linear"),
              ),
          )
  - launch: { box: kf_brightness, property: code }
  - execute: { box: kf_shape, property: code }
  - execute: { box: kf_smoothed, property: code }
  - execute: { box: kf_custom, property: code }
  - await: { wait: pending }
  - wait: { frames: 90 }
  - stop: { box: kf_brightness }

