        println("  frames  sweeps   max |div| after   reduction")
        var first = 0f
        var last = 0f
        for (f in listOf(1, 2, 4, 8)) {
            probe.idle()
            probe.fill(pressureA, 0f)
            probe.fill(pressureB, 0f)
            probe.arm(velocityOut)
            while (probe.stillWaiting()) frame()
