const int RADIX = 256;
#define MAX_SUBGROUP_SIZE 128
#define WORKGROUP_SIZE 512
#define PARTITION_DIVISION 8
const int PARTITION_SIZE = PARTITION_DIVISION * WORKGROUP_SIZE;

