      uint excl = subgroupExclusiveAdd(value);
      uint sum = subgroupAdd(value);

      if (subgroupElect()) {
        intermediate[subgroupIndex] = sum;
      }
      barrier();

      if (index < RADIX / gl_SubgroupSize) {
        uint excl = subgroupExclusiveAdd(intermediate[index]);
        intermediate[index] = excl;
