  - create:
      box: staged_builds
      name: Builds
      frame:
        x: 640.0
        y: 40.0
        w: 300.0
        h: 100.0
      properties:
        autorun: true
        code: |
          // Three stages derived from the level: blockout, traversal and placement.
          // Each reads the level as it was when its build started, and reports what it measured.
          import com.fasterxml.jackson.module.kotlin.jacksonObjectMapper
          import com.fasterxml.jackson.module.kotlin.readValue

          val json = jacksonObjectMapper()
          typealias Cell = Pair<Int, Int>

          // Which room each cell is in, and which neighbouring cells a door joins.
          class Grid(source: String) {
              val level = json.readValue<Map<String, Any?>>(source)
              val rooms = level["rooms"] as Map<String, List<Int>>
              val room = buildMap {
                  for ((id, r) in rooms) for (x in r[0] until r[0] + r[2]) for (y in r[1] until r[1] + r[3]) put(x to y, id)
              }
              val doors = buildSet {
                  for ((_, d) in level["doors"] as Map<String, List<Any>>) {
                      val a = (d[0] as Number).toInt() to (d[1] as Number).toInt()
                      val b = if (d[2] == "e") a.first + 1 to a.second else a.first to a.second + 1
                      add(a to b)
                      add(b to a)
                  }
              }

              fun cell(p: List<Number>) = p[0].toInt() to p[1].toInt()

              val spawn = cell(level["spawn"] as List<Number>)
              val loot = (level["loot"] as Map<String, List<Number>>).mapValues { (_, l) -> cell(l) to l[2].toDouble() }

              fun step(a: Cell, b: Cell) = room[a] != null && room[b] != null && (room[a] == room[b] || (a to b) in doors)
          }

          val blockout = StudyBuildStage(
              "blockout",
              "Blockout",
              "blockout-v1",
              setOf("level"),
              resultNotes = { r -> [StudyBuildNotice(r.facts["summary"].toString(), StudyBuildNoticeKind.INFO)] },
          ) { c ->
                  val g = Grid(c.inputs.getValue("level"))
                  // A floor slab per room, and a wall piece on every cell edge between two rooms, or a room and outside, that is
                  // not a door.
                  val pieces = mutableListOf<List<Double>>()
                  for ((_, r) in g.rooms) pieces +=
                      [r[0].toDouble(), r[1].toDouble(), -0.1, r[2].toDouble(), r[3].toDouble(), 0.1]
                  val walls = mutableSetOf<Pair<Cell, Cell>>()
                  for ((a, _) in g.room) for (b in
                      [
                          a.first + 1 to a.second,
                          a.first to a.second + 1,
                          a.first - 1 to a.second,
                          a.first to a.second - 1,
                      ]) if (g.room[b] != g.room[a] && (a to b) !in g.doors)
                      walls += [a, b].sortedWith(compareBy({ it.first }, { it.second })).let { it[0] to it[1] }
                  for ((a, b) in walls) pieces.add(
                      if (a.second == b.second) [b.first - 0.05, a.second.toDouble(), 0.0, 0.1, 1.0, 1.5]
                      else [a.first.toDouble(), b.second - 0.05, 0.0, 1.0, 0.1, 1.5],
                  )
                  val mesh =
                      pieces
                          .map { p -> boxMesh(p[3], p[4], p[5]).translated(p[0] + p[3] / 2, p[1] + p[4] / 2, p[2] + p[5] / 2) }
                          .reduce { m, n -> m + n }
                  c.file("blockout.obj").writeText(mesh.toObj("blockout"))
                  val area = g.rooms.values.sumOf { it[2] * it[3] }
                  // With Manifold installed, the pieces are also joined into one solid and measured.
                  val solid =
                      if (!afield.geometry.solid.manifold.ManifoldLibrary.isAvailable) null
                      else
                          afield.geometry.solid.manifold.Solid.scope {
                              val joined = afield.geometry.solid.manifold.Solid.union(
                                  pieces.map { p ->
                                      afield.geometry.solid.manifold.Solid.cube(p[3], p[4], p[5]).translated(p[0], p[1], p[2])
                                  },
                              )
                              mapOf("status" to joined.status.toString(), "volume" to joined.volume)
                          }
                  val summary =
                      "${g.rooms.size} rooms, $area cells of floor, ${walls.size} wall pieces, ${g.doors.size / 2} door${if (g.doors.size == 2) "" else "s"}" +
                          (solid?.let { ", joined into one solid of volume ${"%.1f".format(it["volume"])} (${it["status"]})" }
                              ?: "; install Manifold to check it as one solid")
                  StudyBuildProduct(
                      ["blockout.obj"],
                      mapOf(
                          "rooms" to g.rooms.size,
                          "floorCells" to area,
                          "wallPieces" to walls.size,
                          "solid" to solid,
                          "summary" to summary,
                      ),
                  )
              }

          // The shortest walk on the grid from one cell to another, or null.
          fun rough(g: Grid, from: Cell, to: Cell): List<Cell>? {
              val back = mutableMapOf(from to from)
              val queue = ArrayDeque([from])
              while (queue.isNotEmpty()) {
                  val a = queue.removeFirst()
                  if (a == to) return generateSequence(to) { if (it == from) null else back.getValue(it) }.toList().reversed()
                  for (b in
                      [
                          a.first + 1 to a.second,
                          a.first to a.second + 1,
                          a.first - 1 to a.second,
                          a.first to a.second - 1,
                      ]) if (b !in back && g.step(a, b)) {
                      back[b] = a
                      queue.add(b)
                  }
              }
              return null
          }

          // Whether a straight line between two cell centres stays on the floor and passes walls only through doors.
          fun clear(g: Grid, a: Cell, b: Cell): Boolean {
              val n = (max(abs(b.first - a.first), abs(b.second - a.second)) * 8).coerceAtLeast(1)
              var last = a
              for (i in 1..n) {
                  val t = i / n.toDouble()
                  val c = (a.first + (b.first - a.first) * t).roundToInt() to (a.second + (b.second - a.second) * t).roundToInt()
                  if (c == last) continue
                  val ok =
                      if (c.first != last.first && c.second != last.second)
                          (g.step(last, c.first to last.second) && g.step(c.first to last.second, c)) &&
                              (g.step(last, last.first to c.second) && g.step(last.first to c.second, c))
                      else g.step(last, c)
                  if (!ok) return false
                  last = c
              }
              return true
          }

          // The rough walk pulled tight: from each point, straight to the furthest later point in clear view.
          fun relaxed(g: Grid, path: List<Cell>): List<Cell> {
              val out = mutableListOf(path.first())
              var i = 0
              while (i < path.size - 1) {
                  var j = path.size - 1
                  while (j > i + 1 && !clear(g, path[i], path[j])) j--
                  out += path[j]
                  i = j
              }
              return out
          }

          fun length(p: List<Cell>) =
              p.zipWithNext().sumOf { (a, b) -> hypot((b.first - a.first).toDouble(), (b.second - a.second).toDouble()) }
          fun turn(p: List<Cell>) =
              p.windowed(3).sumOf { (a, b, c) ->
                  val u = atan2((b.second - a.second).toDouble(), (b.first - a.first).toDouble())
                  val v = atan2((c.second - b.second).toDouble(), (c.first - b.first).toDouble())
                  abs(Math.toDegrees(atan2(sin(v - u), cos(v - u))))
              }

          val traversal = StudyBuildStage(
              "traversal",
              "Traversal",
              "traversal-v1",
              setOf("level"),
              resultNotes = { r ->
                  (r.facts["loot"] as Map<String, Map<String, Any?>>).map { (id, m) ->
                      if (m["reachable"] != true)
                          StudyBuildNotice("$id cannot be reached from the spawn.", StudyBuildNoticeKind.ERROR)
                      else
                          StudyBuildNotice(
                              "$id: ${m["relaxed"]} along the relaxed path (rough ${m["steps"]}, budget ${m["budget"]}), " +
                                  "turning ${m["turn"]}° (rough ${m["roughTurn"]}°), ${m["doors"]} door${if (m["doors"] == 1) "" else "s"}, seen from ${m["seenBy"]} of the other points." +
                                  (m["shape"]?.let { " $it" } ?: ""),
                              if (m["shape"] != null || m["withinBudget"] != true) StudyBuildNoticeKind.WARNING
                              else StudyBuildNoticeKind.INFO,
                          )
                  }
              },
          ) { c ->
                  val g = Grid(c.inputs.getValue("level"))
                  val points = mapOf("spawn" to g.spawn) + g.loot.mapValues { it.value.first }
                  val paths = mutableMapOf<String, Map<String, Any?>>()
                  val measures = linkedMapOf<String, Map<String, Any?>>()
                  for ((id, target) in g.loot.toSortedMap()) {
                      val (cell, budget) = target
                      val walk = rough(g, g.spawn, cell)
                      if (walk == null) {
                          measures[id] = mapOf("reachable" to false, "budget" to budget)
                          continue
                      }
                      val tight = relaxed(g, walk)
                      fun r1(x: Double) = (x * 10).roundToInt() / 10.0
                      // The route-shape measure: a relaxed path should be no longer, and turn no more, than the walk it came
                      // from.
                      val shape = when {
                          length(tight) > length(walk) + 1e-9 -> "Its relaxed path is longer than its rough walk."
                          turn(tight) > turn(walk) + 1e-9 -> "Its relaxed path turns more than its rough walk."
                          else -> null
                      }
                      measures[id] = mapOf(
                          "reachable" to true,
                          "steps" to walk.size - 1,
                          "relaxed" to r1(length(tight)),
                          "budget" to budget,
                          "withinBudget" to (length(tight) <= budget),
                          "turn" to turn(tight).roundToInt(),
                          "roughTurn" to turn(walk).roundToInt(),
                          "doors" to walk.zipWithNext().count { (a, b) -> g.room[a] != g.room[b] },
                          "seenBy" to points.count { (other, p) -> other != id && clear(g, p, cell) },
                          "shape" to shape,
                      )
                      paths[id] = mapOf(
                          "rough" to walk.map { [it.first, it.second] },
                          "relaxed" to tight.map { [it.first, it.second] },
                      )
                  }
                  val outOfReach =
                      measures
                          .filter { it.value["withinBudget"] != true }
                          .map { (id, m) ->
                              if (m["reachable"] != true) "$id (no path)" else "$id (${m["relaxed"]} > ${m["budget"]})"
                          }
                  c.file("traversal.json").writeText(json.writeValueAsString(mapOf("loot" to measures, "paths" to paths)))
                  StudyBuildProduct(
                      ["traversal.json"],
                      mapOf(
                          "loot" to measures,
                          "outOfReach" to outOfReach,
                          "sightlines" to measures.values.sumOf { (it["seenBy"] as? Int) ?: 0 },
                      ),
                  )
              }

          // Placement waits until every loot point can be reached within its path budget.
          val reachable =
              StudyBuildGate("reachable loot", dependencies = ["traversal"]) { evidence ->
                  val far = evidence.facts("traversal")["outOfReach"] as List<*>
                  if (far.isEmpty()) null else "Out of reach within its path budget: ${far.joinToString()}."
              }

          // Each rule text is compiled once, so the corpus does not compile the same rule for every variant.
          val compiledRules = java.util.concurrent.ConcurrentHashMap<String, (String) -> Map<String, String>>()

          val placement = StudyBuildStage(
              "placement",
              "Placement",
              "placement-v1",
              setOf("reachable loot", "rule"),
              ["traversal"],
              inputHelp = StudyBuildInputHelp("Needs the loot rule", "Run the Loot rule box; placement follows its rule."),
              resultNotes = { r ->
                  [
                      StudyBuildNotice(
                          (r.facts["placed"] as Map<*, *>).entries.joinToString { "${it.key} ${it.value}" } +
                              "; ${r.facts["encounters"]} guarded.",
                          StudyBuildNoticeKind.INFO,
                      ),
                  ]
              },
          ) { c ->
                  val measured =
                      json.readValue<Map<String, Any?>>(c.dependencyFile("traversal", "traversal.json"))["loot"]
                          as Map<String, Map<String, Any?>>
                  // The rule's input: each loot point with its relaxed path length and the doors on the way.
                  val input = measured.toSortedMap().entries.joinToString(", ") { (id, m) -> "$id ${m["relaxed"]} ${m["doors"]}" }
                  val place = compiledRules.getOrPut(c.inputs.getValue("rule")) {
                      QualifiedSource.evaluateKotlin(c.inputs.getValue("rule")) as (String) -> Map<String, String>
                  }
                  val placed = place(input)
                  c.file("rule-input.txt").writeText(input)
                  c.file("placement.json").writeText(json.writeValueAsString(placed))
                  StudyBuildProduct(
                      ["rule-input.txt", "placement.json"],
                      mapOf("placed" to placed, "encounters" to placed.values.count { "guarded" in it }),
                  )
              }

          val stages = [blockout, traversal, placement]
          val gates = [reachable]
          thisBox.properties["levelStages"] = stages
          thisBox.properties["levelGates"] = gates

          val builds = studyBuilds("stages", stages, gates = gates) {
              buildMap {
                  (runCatching { thisBox.named("Level").getPropertyRaw("level") }.getOrNull() as? String)?.let {
                      put("level", it)
                  }
                  (runCatching { thisBox.named("Loot rule").getPropertyRaw("lootRule") }.getOrNull() as? String)?.let {
                      put("rule", it)
                  }
              }
          }
          showStudyBuilds("stages")

          // Draw the current traversal's relaxed paths over the plan, with the Level box's drawing, whenever it changes.
          // The watcher stops when this runner closes, which happens when the box runs again or is stopped.
          go {
              var shown: String? = null
              while (true) {
                  val current = runCatching { builds.stages().first { it.id == "traversal" }.current }.getOrElse { break }
                  if (current != null && current.id != shown) {
                      val draw =
                          thisBox.named("Level").properties["drawLevel"]
                              as? (String, List<List<List<Number>>>, Double) -> List<FLine>
                      if (draw != null) {
                          val found = json.readValue<Map<String, Any?>>(builds.currentFile("traversal", "traversal.json"))
                          val paths = (found["paths"] as Map<String, Map<String, Any?>>).values.map {
                              it["relaxed"] as List<List<Number>>
                          }
                          BoxStudies.show(
                              thisBox,
                              "paths",
                              linesToHTML(draw(current.inputs.getValue("level"), paths, 24.0), 440.0, 240.0, true),
                          )
                          shown = current.id
                      }
                  }
                  kotlinx.coroutines.delay(500)
              }
          }
  - create:
      box: staged_rule
      name: Loot rule
      frame:
        x: 1440.0
        y: 40.0
        w: 300.0
        h: 100.0
      properties:
        autorun: true
        code: |
          // The rule that places loot. It changes only after a replay on real placements: see
          // "Change a rule without breaking what already works" in the Field docs.
          val rule =
              """
          // Placement for one loot point, from the length of its path from the spawn and the doors on the way.
          fun tier(steps: Double, doors: Int) = when {
              doors >= 3 -> "epic guarded"
              doors >= 2 || steps > 16 -> "rare"
              else -> "common"
          }

          // Checks: everything below this line stays as it is.
          fun place(points: String): Map<String, String> {
              val placed = points.split(", ").associate { point ->
                  val (id, steps, doors) = point.split(" ")
                  id to tier(steps.toDouble(), doors.toInt())
              }.toSortedMap()
              for ((id, placement) in placed)
                  check(placement in setOf("common", "rare", "epic guarded")) { id + " got " + placement + ", which is not a placement" }
              check("epic guarded" in placed.values) { "no loot point is epic" }
              return placed
          }
          ::place
          """
                  .trimStart()

          val loot = qualifiedSource(
              "loot",
              rule,
              label = "Loot rule",
              frozen = [FrozenRegion.after("// Checks: everything below this line stays as it is.")],
              control = QualifiedControl("shallow", "L1 4.0 0, L2 6.5 1", "no loot point is epic"),
              fixtures = mapOf(
                  "keep" to
                      QualifiedFixture(
                          "L1 12.4 2, L2 19.1 3, L3 5.0 1",
                          mapOf("L1" to "rare", "L2" to "epic guarded", "L3" to "common"),
                      ),
                  "crypt" to
                      QualifiedFixture(
                          "L1 8.2 1, L2 17.5 1, L3 24.0 3",
                          mapOf("L1" to "common", "L2" to "rare", "L3" to "epic guarded"),
                      ),
                  "mill" to QualifiedFixture("L1 21.3 3, L2 9.9 2", mapOf("L1" to "epic guarded", "L2" to "rare")),
              ),
              // A placement build in this document can be kept as a fixture, with what it placed.
              retain = { attempt ->
                  QualifiedFixture(attempt.file("rule-input.txt").readText(), attempt.record.facts["placed"])
              },
              replayVersion = "loot-replay-1",
          ) { replay ->
                  QualifiedSource.evaluateKotlin(replay.source) as (String) -> Map<String, String>
              }
  - create:
      box: staged_corpus
      name: Corpus
      frame:
        x: 1440.0
        y: 520.0
        w: 300.0
        h: 100.0
      properties:
        autorun: false
        code: |
          import com.fasterxml.jackson.module.kotlin.jacksonObjectMapper
          import com.fasterxml.jackson.module.kotlin.readValue
          import kotlinx.coroutines.*

          // Seeded variants of the level, built by the same stages and shown side by side.
          // Nothing here asks a model: it is the machine run many times. Run this box to build them.

          val json = jacksonObjectMapper()
          val seeds = 0..5

          // Seed 0 is the level as it is. Other seeds shift each door along its wall, and may drop a room with one door.
          fun variant(source: String, seed: Int): String {
              if (seed == 0) return source
              val random = java.util.Random(seed.toLong())
              val level = json.readValue<MutableMap<String, Any?>>(source)
              val rooms = (level["rooms"] as Map<String, List<Int>>).toMutableMap()
              val doors = (level["doors"] as Map<String, List<Any>>).toMutableMap()
              val loot = (level["loot"] as Map<String, List<Any>>).toMutableMap()
              fun roomAt(x: Int, y: Int) =
                  rooms.entries.firstOrNull { (_, r) -> x in r[0] until r[0] + r[2] && y in r[1] until r[1] + r[3] }?.key
              val spawn = level["spawn"] as List<Int>
              val leaves =
                  rooms.keys.filter { id ->
                      id != roomAt(spawn[0], spawn[1]) &&
                          doors.values.count { d ->
                              val x = (d[0] as Number).toInt()
                              val y = (d[1] as Number).toInt()
                              id == roomAt(x, y) || id == (if (d[2] == "e") roomAt(x + 1, y) else roomAt(x, y + 1))
                          } == 1
                  }
              if (leaves.isNotEmpty() && random.nextBoolean()) {
                  val gone = leaves[random.nextInt(leaves.size)]
                  rooms.remove(gone)
                  doors.entries.removeIf { (_, d) ->
                      val x = (d[0] as Number).toInt()
                      val y = (d[1] as Number).toInt()
                      roomAt(x, y) == null || (if (d[2] == "e") roomAt(x + 1, y) else roomAt(x, y + 1)) == null
                  }
                  loot.entries.removeIf { (_, l) -> roomAt((l[0] as Number).toInt(), (l[1] as Number).toInt()) == null }
              }
              for ((id, d) in doors.toMap()) {
                  val x = (d[0] as Number).toInt()
                  val y = (d[1] as Number).toInt()
                  val a = roomAt(x, y)
                  val b = if (d[2] == "e") roomAt(x + 1, y) else roomAt(x, y + 1)
                  val shift = random.nextInt(5) - 2
                  val (nx, ny) = if (d[2] == "e") x to y + shift else x + shift to y
                  val na = roomAt(nx, ny)
                  val nb = if (d[2] == "e") roomAt(nx + 1, ny) else roomAt(nx, ny + 1)
                  if (na == a && nb == b) doors[id] = [nx, ny, d[2]]
              }
              if (loot.isEmpty()) return source
              return json.writeValueAsString(level + mapOf("rooms" to rooms, "doors" to doors, "loot" to loot))
          }

          fun runCorpus(checkActive: () -> Unit) {
              val stages = thisBox.named("Builds").properties["levelStages"] as List<StudyBuildStage>
              val gates = thisBox.named("Builds").properties["levelGates"] as List<StudyBuildGate>
              val draw =
                  thisBox.named("Level").properties["drawLevel"] as (String, List<List<List<Number>>>, Double) -> List<FLine>
              val level = thisBox.named("Level").getPropertyRaw("level") as String
              val rule = thisBox.named("Loot rule").getPropertyRaw("lootRule") as String
              val tiles = seeds.map { seed ->
                  checkActive()
                  BoxStudies.show(
                      thisBox,
                      "gallery",
                      "<p style='color:#999'>Building variant ${seed + 1} of ${seeds.count()}…</p>",
                  )
                  val source = variant(level, seed)
                  val builds =
                      studyBuilds("variant$seed", stages, workers = 1, gates = gates) { mapOf("level" to source, "rule" to rule) }
                  fun build(stage: String): StudyBuildRecord? {
                      checkActive()
                      val state = builds.stages().first { it.id == stage }
                      return state.current ?: state.fingerprint?.let { builds.await(builds.start(stage, it).id) }
                  }
                  build("blockout")
                  val walk = build("traversal")
                  val placed = build("placement")
                  val traversal = walk?.let {
                      json.readValue<Map<String, Any?>>(builds.currentFile("traversal", "traversal.json"))
                  }
                  val paths = (traversal?.get("paths") as? Map<String, Map<String, Any?>>).orEmpty().values.map {
                      it["relaxed"] as List<List<Number>>
                  }
                  val measures = (traversal?.get("loot") as? Map<String, Map<String, Any?>>).orEmpty()
                  val worst =
                      measures.values
                          .mapNotNull { m ->
                              (m["relaxed"] as? Number)?.toDouble()?.div((m["steps"] as Number).toDouble().coerceAtLeast(1.0))
                          }
                          .maxOrNull()
                  val caption = [
                      if (seed == 0) "the level as it is"
                      else "seed $seed · ${(json.readValue<Map<String, Any?>>(source)["rooms"] as Map<*, *>).size} rooms",
                      "within budget ${measures.values.count { it["withinBudget"] == true }} of ${measures.size} · sightlines ${walk?.facts?.get("sightlines") ?: "–"}",
                      "longest relaxed/rough ${worst?.let { "%.2f".format(it) } ?: "–"}",
                      when {
                          placed?.status == StudyBuildStatus.SUCCEEDED ->
                              "placed: " +
                                  (placed.facts["placed"] as Map<*, *>).entries.joinToString { e -> "${e.key} ${e.value}" }
                          placed != null -> "placement failed: ${placed.message}"
                          else ->
                              "placement waits: " +
                                  (builds.stages().first { it.id == "placement" }.reason ?: "").removePrefix(
                                      "Waiting for reachable loot: ",
                                  )
                      },
                  ]
                  "<div style='width:220px'>" +
                      drawToSVG(draw(source, paths, 12.0), 220.0, 120.0) +
                      caption.joinToString("") {
                          "<p style='margin:3px 0 0;color:#bbb;font:11px/1.3 Iosevka,monospace'>$it</p>"
                      } +
                      "</div>"
              }
              checkActive()
              BoxStudies.show(
                  thisBox,
                  "gallery",
                  "<div style='display:grid;grid-template-columns:repeat(3,220px);gap:16px;background:#000;padding:16px;border-radius:12px'>" +
                      tiles.joinToString("") +
                      "</div>",
              )
          }

          // Stop interrupts the current wait and prevents later variants from being installed.
          val ownerRun = RunScope.current()
          go {
              val activeContext = currentCoroutineContext()
              try {
                  runInterruptible(Dispatchers.IO) {
                      RunScope.withCurrent(ownerRun) { runCorpus { activeContext.ensureActive() } }
                  }
              } catch (cancelled: CancellationException) {
                  throw cancelled
              } catch (e: Exception) {
                  ensureActive()
                  BoxStudies.show(
                      thisBox,
                      "gallery",
                      "<p style='color:#ff6969;user-select:text'>The corpus stopped: ${e.message}</p>",
                  )
              }
          }
  - connect:
      parent: staged_level
      child: staged_builds
  - connect:
      parent: staged_rule
      child: staged_builds
  - connect:
      parent: staged_builds
      child: staged_corpus
  - execute:
      box: staged_start
